mapper.select:
SELECT p.id, p.type, p.slug, CASE WHEN p.type = 'TECH' THEN p.title WHEN CHAR_LENGTH(p.content) > 60 THEN CONCAT(LEFT(p.content, 60), '…') ELSE p.content END AS label, p.published_at AS publishedAt
FROM post p WHERE p.deleted = 0 AND p.status = 'PUBLISHED' AND p.published_at IS NOT NULL AND p.published_at <= UTC_TIMESTAMP(3) AND ( #{type} = 'ALL' OR p.type = #{type} )
AND YEAR(p.published_at) = #{year}
ORDER BY p.published_at DESC, p.id DESC
LIMIT #{pageSize} OFFSET #{offset}
